// Une recherche par ligne : adapte la liste aux postes que tu vises.
// Quota JSearch gratuit : 200 requêtes/mois -> 6 recherches/jour max.
const recherches = [
  "stage growth marketing Paris",
  "stage business development Paris",
  "stage business developer startup",
  "growth intern Paris",
  "stage marketing acquisition startup Paris",
  "stage sales ops revenue operations Paris"
];
return recherches.map(q => ({ json: { query: q } }));

// Transforme les réponses JSearch en une offre par item, avec des champs standard.
// Accepte data = liste OU data.jobs = liste (le format de l'API a déjà changé une fois).
const offres = [];
for (const item of $input.all()) {
  const d = item.json.data;
  const jobs = Array.isArray(d) ? d : (d && Array.isArray(d.jobs) ? d.jobs : []);
  for (const j of jobs) {
    offres.push({ json: {
      titre: j.job_title || "",
      entreprise: j.employer_name || "",
      site_entreprise: j.employer_website || "",
      lien_offre: j.job_apply_link || (j.apply_options && j.apply_options[0] && j.apply_options[0].apply_link) || j.job_google_link || "",
      source: "JSearch - " + (j.job_publisher || "web"),
      ville: j.job_location || j.job_city || "",
      description: j.job_description || "",
      id: j.job_id || j.job_apply_link || (j.job_title + "|" + j.employer_name)
    }});
  }
}
return offres;

// Recherches de posts LinkedIn publics qui annoncent un stage.
// Chaque recherche coûte 1 crédit Tavily (1000 gratuits/mois).
const recherches = [
  "recrute stagiaire growth",
  "on recrute stage business development",
  "nous recrutons stagiaire marketing startup",
  "hiring growth intern Paris"
];
return recherches.map(q => ({ json: { query: q } }));

// Ne garde que les vrais posts (pas les profils ni les pages entreprise).
const vus = new Set(); const posts = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    const url = r.url || "";
    if (!(url.includes("/posts/") || url.includes("/feed/update/"))) continue;
    const cle = url.split('?')[0].replace(/^https?:\/\/[a-z]+\.linkedin\.com/, 'https://linkedin.com');
    if (vus.has(cle)) continue; vus.add(cle);
    posts.push({ json: { id: cle, lien_offre: url, titre_post: r.title || "", contenu: (r.content || "").slice(0, 2000) } });
  }
}
return posts;

