// Garde uniquement les profils LinkedIn (/in/) qui mentionnent bien l'entreprise qui recrute.
// C'est ce filtre qui évite de contacter quelqu'un d'une autre boîte (ex. Poppins -> une CMO d'Upstart).
const offre = $('Résultat IA').item.json;
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const motsEntreprise = norm(offre.entreprise)
  .replace(/\b(sas|sa|sarl|group|groupe|france|inc|ltd|the)\b/g, ' ')
  .split(/[^a-z0-9]+/).filter(m => m.length > 2);

const profils = [];
for (const r of ($json.results || [])) {
  const url = r.url || '';
  if (!url.includes('linkedin.com/in/')) continue;
  const texte = norm((r.title || '') + ' ' + (r.content || ''));
  if (!motsEntreprise.length || !motsEntreprise.every(m => texte.includes(m))) continue;
  profils.push((r.title || '') + ' | ' + url + '\n' + (r.content || '').slice(0, 500));
}

// Si l'offre vient d'un post LinkedIn, son auteur est un candidat naturel.
const auteur = (offre.source || '').startsWith('Post LinkedIn de ') ? offre.source.replace('Post LinkedIn de ', '') : '';
if (auteur) profils.unshift('AUTEUR DU POST QUI ANNONCE LE STAGE : ' + auteur + ' | lien du post : ' + offre.lien_offre);

return { json: { ...offre, profils: profils.join('\n\n---\n\n'), nb_profils: profils.length } };

// Lit la réponse de l'IA sans planter si le JSON est cassé, et la fusionne avec l'offre.
const offre = $('Filtrer profils').item.json;
let c = {};
try { c = JSON.parse($json.choices[0].message.content); } catch (e) {}
// Garde-fou : l'URL doit faire partie des profils fournis (l'IA ne doit rien inventer).
const urlOk = c.contact_linkedin && (offre.profils || '').includes(c.contact_linkedin);
const nom = urlOk || (c.contact_nom && (offre.profils || '').includes(c.contact_nom)) ? (c.contact_nom || '') : '';
return { json: {
  ...offre,
  contact_nom: nom,
  contact_poste: nom ? (c.contact_poste || '') : '',
  contact_linkedin: urlOk ? c.contact_linkedin : '',
  pourquoi_contact: nom ? (c.pourquoi || '') : 'Aucun profil fiable de l\'entreprise trouvé',
  confiance: nom ? (c.confiance || 'faible') : 'aucune'
} };

// Rassemble tout ce que l'IA a le droit d'utiliser pour écrire.
const o = $('Contact choisi').item.json;
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const nomFamille = norm((o.contact_nom || '').trim().split(/\s+/).slice(-1)[0]);

// Infos sur la personne : on ne garde que les résultats qui la citent ET parlent de l'entreprise ou viennent de LinkedIn (évite les homonymes).
const motEntreprise = norm(o.entreprise).split(/[^a-z0-9]+/).filter(m => m.length > 2)[0] || '';
const infos = ($('Recherche sur la personne').item.json.results || [])
  .filter(r => {
    const t = norm(r.title + ' ' + r.content);
    if (!nomFamille) return true;
    return t.includes(nomFamille) && ((motEntreprise && t.includes(motEntreprise)) || (r.url || '').includes('linkedin.com'));
  })
  .map(r => '- ' + (r.title || '') + ' (' + (r.url || '') + ')' + (r.published_date ? ' [' + r.published_date + ']' : '') + '\n  ' + (r.content || '').slice(0, 700))
  .join('\n');

const actus = ($json.results || [])
  .map(r => '- ' + (r.title || '') + (r.published_date ? ' [' + r.published_date + ']' : '') + ' : ' + (r.content || '').slice(0, 350))
  .join('\n');

return { json: {
  ...o,
  infos_personne: infos || 'Rien trouvé sur cette personne.',
  actus: actus || 'Aucune actualité récente.'
} };

// Assemble la fiche finale et décide si elle part en "À contacter" ou en "À relire".
const c = $('Contexte').item.json;
const parse = s => { try { return JSON.parse(s); } catch (e) { return {}; } };
const brouillon = parse($('Message IA').item.json.choices?.[0]?.message?.content);
const finale = parse($json.choices?.[0]?.message?.content);

const connexion = (finale.message_connexion || brouillon.message_connexion || '').trim();
const suivi = (finale.message_suivi || brouillon.message_suivi || '').trim();
const note = Number(finale.note_personnalisation ?? 0);

// Dernier filet de sécurité, sans IA.
const interdits = ['je me permets', "n'hésitez pas", 'passionné', 'dynamique', 'opportunité', 'votre parcours',
  'impressionn', "j'espère que vous allez bien", 'cordialement', 'synergie', '—'];
const texte = (connexion + ' ' + suivi).toLowerCase();
const problemes = [];
if (!connexion || !suivi) problemes.push('message manquant');
if (connexion.length > 200) problemes.push('note de connexion trop longue (' + connexion.length + ' car.)');
const trouves = interdits.filter(f => texte.includes(f));
if (trouves.length) problemes.push('formules à éviter : ' + trouves.join(', '));
if (!['haute', 'moyenne'].includes(c.confiance)) problemes.push('contact incertain');
if (note < 7) problemes.push('personnalisation ' + note + '/10');

return { json: {
  titre: c.titre, entreprise: c.entreprise, lien_offre: c.lien_offre, source: c.source, id: c.id,
  score: c.score, raison: c.raison,
  contact_nom: c.contact_nom, contact_poste: c.contact_poste,
  // Pas de profil fiable : lien vers une recherche LinkedIn des gens de l'entreprise.
  contact_linkedin: c.contact_linkedin || ('https://www.linkedin.com/search/results/people/?keywords=' + encodeURIComponent(c.entreprise)),
  pourquoi_contact: c.pourquoi_contact, confiance: c.confiance,
  accroche: brouillon.accroche || '', preuve: brouillon.preuve_utilisee || '',
  message_connexion: connexion, message_suivi: suivi,
  personnalisation: note,
  statut: problemes.length ? 'À relire' : 'À contacter',
  raison_relecture: problemes.join(' ; ') + (finale.corrections ? (problemes.length ? ' | ' : '') + 'Relecteur : ' + finale.corrections : '')
} };

// Clé stable : même entreprise + même poste = même offre, quelle que soit la source.
// L'identifiant JSearch ou l'URL changent selon le site, pas cette clé.
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const formes = new Set(['sas','sa','sarl','group','groupe','france','inc','ltd','the']);
const vides = new Set(['stage','stagiaire','intern','internship','h','f','m','x','hf','fh','mf','fm','de','du','des','la','le','les','en','et','a','au','un','une','of','and','in','for','paris','france','mois','6','janvier','2027','startup']);
return $input.all().map(item => {
  const j = item.json;
  const entreprise = norm(j.entreprise).split(' ').filter(m => m && !formes.has(m)).join(' ');
  const poste = [...new Set(norm(j.titre).split(' ').filter(m => m && !vides.has(m)))].sort().join(' ');
  const id = entreprise && poste ? entreprise + '|' + poste : j.id;
  return { json: { ...j, id_source: j.id, id } };
});

// Retire les offres déjà présentes dans la base Notion.
// Compare avec la clé entreprise + poste, l'ID offre et le lien de l'offre.
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const formes = new Set(['sas','sa','sarl','group','groupe','france','inc','ltd','the']);
const vides = new Set(['stage','stagiaire','intern','internship','h','f','m','x','hf','fh','mf','fm','de','du','des','la','le','les','en','et','a','au','un','une','of','and','in','for','paris','france','mois','6','janvier','2027','startup']);
const cle = (entreprise, titre) => {
  const e = norm(entreprise).split(' ').filter(m => m && !formes.has(m)).join(' ');
  const p = [...new Set(norm(titre).split(' ').filter(m => m && !vides.has(m)))].sort().join(' ');
  return e && p ? e + '|' + p : '';
};
const texte = p => {
  if (!p) return '';
  if (p.type === 'url') return p.url || '';
  return (p[p.type] || []).map(t => t.plain_text || '').join('');
};
const connus = new Set();
let lignes = 0;
for (const item of $input.all()) {
  const props = item.json.properties;
  if (!props) continue;
  lignes++;
  const titre = Object.values(props).find(p => p.type === 'title');
  for (const v of [cle(texte(titre), texte(props['Poste'])), texte(props['ID offre']), texte(props['Lien offre'])]) {
    if (v) connus.add(v);
  }
}
const offres = $('Doublons du jour').all();
const gardees = offres.filter(o => ![o.json.id, o.json.id_source, o.json.lien_offre].some(v => v && connus.has(v)));
console.log(`Notion : ${lignes} lignes lues, ${offres.length - gardees.length} doublons retirés, ${gardees.length} offres gardées`);
return gardees;

// Repère les lignes en double dans Notion et choisit lesquelles mettre à la corbeille.
// Doublon = même entreprise + même poste, ou même ID offre.
// On ne touche jamais à une ligne déjà travaillée (statut autre que À contacter / À relire).
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const formes = new Set(['sas','sa','sarl','group','groupe','france','inc','ltd','the']);
const vides = new Set(['stage','stagiaire','intern','internship','h','f','m','x','hf','fh','mf','fm','de','du','des','la','le','les','en','et','a','au','un','une','of','and','in','for','paris','france','mois','6','janvier','2027','startup']);
const cle = (entreprise, titre) => {
  const e = norm(entreprise).split(' ').filter(m => m && !formes.has(m)).join(' ');
  const p = [...new Set(norm(titre).split(' ').filter(m => m && !vides.has(m)))].sort().join(' ');
  return e && p ? e + '|' + p : '';
};
const texte = p => {
  if (!p) return '';
  if (p.type === 'select') return p.select ? p.select.name : '';
  return (p[p.type] || []).map(t => t.plain_text || '').join('');
};
const lignes = $input.all().map(i => i.json).filter(j => j.properties).map(j => {
  const titre = texte(Object.values(j.properties).find(p => p.type === 'title'));
  return { page_id: j.id, entreprise: titre, poste: texte(j.properties['Poste']), statut: texte(j.properties['Statut']),
    cree: j.created_time || '', cles: [cle(titre, texte(j.properties['Poste'])), texte(j.properties['ID offre'])].filter(Boolean) };
});
// Regroupe les lignes qui partagent une clé (union-find).
const parent = lignes.map((_, i) => i);
const racine = i => parent[i] === i ? i : (parent[i] = racine(parent[i]));
const vu = new Map();
lignes.forEach((l, i) => l.cles.forEach(c => { if (vu.has(c)) parent[racine(i)] = racine(vu.get(c)); else vu.set(c, i); }));
const groupes = new Map();
lignes.forEach((l, i) => { const r = racine(i); groupes.set(r, [...(groupes.get(r) || []), l]); });

const sansAction = new Set(['À contacter', 'À relire', '']);
const aSupprimer = [];
for (const g of groupes.values()) {
  if (g.length < 2) continue;
  const intactes = g.filter(l => sansAction.has(l.statut));
  // Une ligne travaillée existe : toutes les intactes partent. Sinon on garde la plus récente, en préférant À contacter.
  const gardee = intactes.length === g.length
    ? [...g].sort((a, b) => (a.statut === 'À contacter' ? 0 : 1) - (b.statut === 'À contacter' ? 0 : 1) || b.cree.localeCompare(a.cree))[0]
    : null;
  for (const l of intactes) if (l !== gardee) aSupprimer.push(l);
}
// Garde-fou : au-delà de la moitié de la base, c'est sûrement un bug. On ne supprime rien.
if (aSupprimer.length > lignes.length / 2) {
  console.log(`Nettoyage annulé : ${aSupprimer.length} lignes sur ${lignes.length} seraient supprimées.`);
  return [];
}
console.log(`Nettoyage Notion : ${aSupprimer.length} doublons mis à la corbeille sur ${lignes.length} lignes`);
return aSupprimer.map(l => ({ json: { page_id: l.page_id, entreprise: l.entreprise, poste: l.poste, statut: l.statut } }));
